INSERT INTO `blog_post` VALUES (1,'Châu Anh',NULL,'2024-12-25 16:19:41.944299','hoa.jpg','\'Hoa xuân trong gió xuân\' - chân dung phụ nữ vùng Tây Bắc',NULL,'<p>T&aacute;c giả Đỗ B&iacute;ch Th&uacute;y viết về c&ocirc; g&aacute;i d&acirc;n tộc d&aacute;m theo đuổi t&igrave;nh y&ecirc;u, c&ocirc; gi&aacute;o b&aacute;m trụ v&ugrave;ng cao trong tập truyện &quot;Hoa xu&acirc;n trong gi&oacute; xu&acirc;n&quot;.</p>\r\n\r\n<p>S&aacute;ch do C&ocirc;ng ty Li&ecirc;n Việt v&agrave; NXB Hội nh&agrave; văn li&ecirc;n kết ấn h&agrave;nh, gồm 19 c&acirc;u chuyện chọn lọc, trong đ&oacute; c&oacute; những s&aacute;ng t&aacute;c cũ v&agrave; mới. T&aacute;c giả đề cập đến đề t&agrave;i người d&acirc;n tộc thiểu số, cuộc sống sinh hoạt của người T&agrave;y, M&ocirc;ng v&agrave; c&acirc;u chuyện xoay quanh t&igrave;nh y&ecirc;u, c&aacute;c mối quan hệ của họ.</p>\r\n\r\n<p>Truyện mở đầu&nbsp;<em>Hoa xu&acirc;n trong gi&oacute; xu&acirc;n</em>&nbsp;n&oacute;i về c&ocirc; g&aacute;i Ch&iacute;a kh&ocirc;ng chấp nhận cưới người kh&ocirc;ng y&ecirc;u m&agrave; tự đi t&igrave;m hạnh ph&uacute;c. Được mẹ b&agrave;y c&aacute;ch, c&ocirc; bỏ trốn<strong>&nbsp;</strong>với người y&ecirc;u ngay trong đ&aacute;m cưới. Sau<strong>&nbsp;</strong>một th&aacute;ng, đ&ocirc;i trẻ được bố Ch&iacute;a v&agrave; hai b&ecirc;n gia đ&igrave;nh chấp thuận: &quot;Chả về m&agrave; chuẩn bị đ&aacute;m hỏi chứ g&igrave; nữa. Để con g&aacute;i tao ở lại đ&acirc;y, cưới mới được đ&oacute;n&quot;, &ocirc;ng y&ecirc;u cầu ch&agrave;ng trai về nh&agrave; thưa chuyện với bố mẹ để hỏi cưới con g&aacute;i m&igrave;nh. Truyện kết th&uacute;c ở cảnh hai người y&ecirc;u nhau đến được với nhau. C&ocirc; g&aacute;i đứng dưới t&aacute;n c&acirc;y mận nh&igrave;n theo b&oacute;ng người y&ecirc;u, những b&ocirc;ng hoa mận rơi lả tả trong gi&oacute; xu&acirc;n.</p>\r\n\r\n<p>Cuốn s&aacute;ch viết về t&igrave;nh cảm gia đ&igrave;nh, d&ugrave; ở v&ugrave;ng cao hay th&agrave;nh phố, cha mẹ lu&ocirc;n hy sinh v&igrave; con.&nbsp;<em>Kh&aacute;ch qu&yacute;</em>&nbsp;cho thấy h&igrave;nh ảnh người mẹ d&acirc;n tộc nhớ thương con đi l&agrave;m xa: &quot;Ch&aacute;u ngoại ơi, ch&aacute;u ngoại ơi. Mang mẹ về cho b&agrave; với chứ&quot;. T&igrave;nh cảm của mẹ d&agrave;nh cho con trai nu&ocirc;i được thể hiện qua&nbsp;<em>Chiếc hộp khảm trai</em>, hay trong truyện&nbsp;<em>Em như sợi chỉ xanh</em>, bố mẹ của Vi b&aacute;n cả mảnh đất, t&agrave;i sản lớn nhất được truyền lại từ đời &ocirc;ng b&agrave; để con g&aacute;i đ&atilde; qu&aacute; lứa lỡ th&igrave; lấy được chồng.</p>\r\n\r\n<p>Tập truyện c&ograve;n viết về ch&acirc;n dung những thầy, c&ocirc; gi&aacute;o b&aacute;m trụ v&ugrave;ng cao, mang con chữ đến cho học tr&ograve; miền n&uacute;i. Truyện&nbsp;<em>Ấm &aacute;p như nước</em>&nbsp;khắc họa h&igrave;nh ảnh c&ocirc; gi&aacute;o Hi&ecirc;n lu&ocirc;n t&igrave;m c&aacute;ch duy tr&igrave; sĩ số lớp, vận động phụ huynh v&agrave; học sinh đến trường. C&ocirc; đi từng nh&agrave;, d&ugrave;ng mọi l&yacute; lẽ thuyết phục, chấp nhận uống năm ch&eacute;n rượu ng&ocirc; để gia đ&igrave;nh cho c&aacute;c em đi học, tr&ecirc;n đường đ&oacute;n học sinh, c&ocirc; bị ng&atilde;: &quot;Chả c&oacute; ai tr&ecirc;n đời n&agrave;y biết rằng c&ocirc; vừa bị ng&atilde; l&uacute;c đi đ&oacute;n thằng b&eacute;, b&ugrave;n ướt sũng từ g&oacute;t ch&acirc;n tới m&ocirc;ng quần&quot;. Hi&ecirc;n đem l&ograve;ng th&iacute;ch Khải, thầy gi&aacute;o ở một điểm trường kh&aacute;c.</p>\r\n\r\n<p>Theo t&aacute;c giả, nguy&ecirc;n mẫu của nh&acirc;n vật ch&iacute;nh trong truyện l&agrave; một c&ocirc; gi&aacute;o ở X&iacute;n Mần, v&ugrave;ng cực t&acirc;y của tỉnh H&agrave; Giang đ&atilde; gắn b&oacute; với miền n&uacute;i suốt 30 năm. Trong truyện c&oacute; đoạn: &quot;Hi&ecirc;n lẽ ra chẳng l&ecirc;n c&aacute;i nơi chon von cơ cực n&agrave;y l&agrave;m g&igrave; nếu như kh&ocirc;ng phải chạy trốn khổ đau. L&uacute;c đầu l&agrave; thế, rồi dần dần quen, rồi thương, rồi gắn b&oacute;. Đến cả m&ugrave;i ph&acirc;n tr&acirc;u ph&acirc;n b&ograve; cũng thấy quen mũi rồi&quot;.</p>\r\n\r\n<p>Kh&ocirc;ng g&oacute;i gọn bối cảnh ở v&ugrave;ng n&uacute;i, Đỗ B&iacute;ch Th&uacute;y đưa người đọc xu&ocirc;i về th&agrave;nh phố với những c&acirc;u chuyện nơi g&oacute;c phố nhỏ, về cốt c&aacute;ch người H&agrave; Nội. Truyện&nbsp;<em>Chiếc hộp khảm trai&nbsp;</em>l&agrave; g&oacute;c nh&igrave;n của B&igrave;nh - con d&acirc;u - về mẹ chồng, một<strong>&nbsp;</strong>phụ nữ thủ đ&ocirc;. B&agrave; ăn mặc tươm tất, lịch sự ở tuổi 70 v&agrave; lu&ocirc;n giữ nh&agrave; cửa ngăn nắp, &quot;kh&ocirc;ng một hạt bụi&quot;. Nh&agrave; văn viết trong t&aacute;c phẩm: &quot;Sự cẩn thận, đ&uacute;ng lề th&oacute;i, một nếp ăn th&oacute;i ở c&oacute; lẽ từ l&acirc;u lắm trong b&agrave;. B&igrave;nh hay đứng tr&ecirc;n ban c&ocirc;ng tầng hai, nh&igrave;n qua những c&aacute;i l&aacute; nhỏ của c&acirc;y hoa giấy, ngắm mẹ chồng khẽ n&acirc;ng t&agrave; &aacute;o d&agrave;i, nhẹ nh&agrave;ng bước ch&acirc;n ngồi v&agrave;o x&iacute;ch l&ocirc;, lưng lu&ocirc;n thẳng&quot;. B&agrave; c&ograve;n l&agrave; chỗ dựa tinh thần cho con trai v&agrave; con d&acirc;u, lu&ocirc;n t&ocirc;n trọng sở th&iacute;ch, lối sống của hai con. B&igrave;nh x&oacute;t xa khi mẹ chồng bị bệnh: &quot;Bấy l&acirc;u, mẹ như một chỗ dựa cho hai vợ chồng những l&uacute;c b&aacute;t đũa x&ocirc; lệch, nay mẹ nằm một chỗ, sự hẫng hụt đ&atilde; th&agrave;nh một khoảng trống rất lớn&quot;.</p>\r\n\r\n<p>L&agrave; nh&agrave; văn chuy&ecirc;n viết về đề t&agrave;i miền n&uacute;i, trong buổi ra mắt s&aacute;ch ng&agrave;y 24/11, Đỗ B&iacute;ch Th&uacute;y n&oacute;i l&yacute; do đưa một số t&aacute;c phẩm về H&agrave; Nội v&agrave;o tập truyện: &quot;Những truyện ngắn n&agrave;y t&ocirc;i viết do kh&ocirc;ng kiềm chế được, qu&aacute; th&iacute;ch H&agrave; Nội n&ecirc;n mới đưa v&agrave;o&quot;. Chị cho biết kh&ocirc;ng qu&aacute; tự tin về đề t&agrave;i n&agrave;y bởi đ&atilde; c&oacute; nhiều người viết về thủ đ&ocirc; trước m&igrave;nh.</p>\r\n\r\n<p><img alt=\"Nhà văn Đỗ Bích Thúy cho biết dành sự ưu tiên để viết về miền núi. Ảnh: Hội Nhà văn Việt Nam\" src=\"https://i1-giaitri.vnecdn.net/2024/12/14/screenshot-4-1732696464-1847-1-6712-5417-1734189931.png?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=dZYGJnfbe_n-odJuZKj5PA\" /></p>\r\n\r\n<p>Nh&agrave; văn Đỗ B&iacute;ch Th&uacute;y cho biết sẽ ưu ti&ecirc;n viết về đề t&agrave;i miền n&uacute;i. Ảnh:&nbsp;<em>Hội Nh&agrave; văn Việt Nam</em></p>\r\n\r\n<p>T&aacute;c giả sử dụng văn phong tự nhi&ecirc;n, ng&ocirc;n từ giản dị v&agrave; mi&ecirc;u tả cảnh, vật một c&aacute;ch chi tiết. Nh&agrave; văn Nguyễn Văn Thọ nhận x&eacute;t về cuốn s&aacute;ch: &quot;Từ đề t&agrave;i miền n&uacute;i, hiện thực v&agrave; l&atilde;ng mạn, bay l&ecirc;n như&nbsp;<em>Tiếng đ&agrave;n m&ocirc;i b&ecirc;n bờ r&agrave;o đ&aacute;</em>, văn chương nh&agrave; văn xuất th&acirc;n từ miền n&uacute;i n&agrave;y, sau hơn chục năm gần đ&acirc;y bắt đầu len lỏi v&agrave;o c&aacute;i s&acirc;u thẳm của đất ng&agrave;n năm, m&agrave; ở đ&oacute; Đỗ B&iacute;ch Th&uacute;y vẫn giữ được g&oacute;c nh&igrave;n hết sức nh&acirc;n hậu v&agrave; bản lĩnh&quot;.</p>\r\n\r\n<p>Đỗ B&iacute;ch Th&uacute;y sinh năm 1975 tại H&agrave; Giang, hiện sống ở H&agrave; Nội. Chị từng l&agrave; Ph&oacute; Tổng bi&ecirc;n tập&nbsp;<em>Tạp ch&iacute; Văn nghệ qu&acirc;n đội</em>&nbsp;trong mười năm. Nh&agrave; văn nổi tiếng với c&aacute;c t&aacute;c phẩm đề t&agrave;i miền n&uacute;i như:&nbsp;<a href=\"https://vnexpress.net/tieng-dan-moi-sau-bo-rao-da-2141685.html\"><em>Tiếng đ&agrave;n m&ocirc;i sau bờ r&agrave;o đ&aacute;</em></a>&nbsp;(2005),&nbsp;<a href=\"https://vnexpress.net/do-bich-thuy-quay-lai-de-tai-vung-cao-voi-chua-dat-3302362.html\"><em>Ch&uacute;a đất&nbsp;</em></a>(2015),&nbsp;<em>Lặng y&ecirc;n dưới vực s&acirc;u (</em>2017),&nbsp;<em>Người y&ecirc;u ơi</em>&nbsp;(2021),&nbsp;<em>Than đỏ dưới tro t&agrave;n&nbsp;</em>(2023). Trong đ&oacute;, truyện ngắn&nbsp;<em>Tiếng đ&agrave;n m&ocirc;i sau bờ r&agrave;o đ&aacute;&nbsp;</em>được chuyển thể th&agrave;nh phim điện ảnh&nbsp;<a href=\"https://vnexpress.net/chuyen-cua-pao-trong-sang-va-nhan-van-1888012.html\"><em>Chuyện của Pao</em></a><a href=\"https://vnexpress.net/chuyen-cua-pao-trong-sang-va-nhan-van-1888012.html\">&nbsp;</a>v&agrave; đoạt giải thưởng<strong>&nbsp;</strong><a href=\"https://vnexpress.net/canh-dieu-vang-2005-them-nhieu-giai-cho-dao-dien-1887643.html\">C&aacute;nh Diều V&agrave;ng</a>&nbsp;năm 2005, bộ phim truyền h&igrave;nh&nbsp;<em>Lặng y&ecirc;n dưới vực s&acirc;u</em>&nbsp;của đạo diễn Đ&agrave;o Duy Ph&uacute;c cũng dựa tr&ecirc;n t&aacute;c phẩm c&ugrave;ng t&ecirc;n của Đỗ B&iacute;ch Th&uacute;y.</p>\r\n','25/12/2024 16:19:41'),(2,'Châu Anh',NULL,'2024-12-25 16:20:35.913658','maxresdefault.jpg','Thân phận phụ nữ trong \'Còn một đợt rét chót, đêm nay sẽ về\'',NULL,'<p>Nh&agrave; văn Trang Thụy kể c&acirc;u chuyện c&ocirc; g&aacute;i d&acirc;n tộc kh&ocirc;ng chấp nhận chung chồng trong tập truyện ngắn đầu tay.</p>\r\n\r\n<p>S&aacute;ch do NXB Hội Nh&agrave; văn ph&aacute;t h&agrave;nh, gồm 11 truyện ngắn được sắp xếp theo tiến tr&igrave;nh s&aacute;ng t&aacute;c từ năm 2021 đến nay. T&aacute;c giả viết về m&ugrave;a đ&ocirc;ng, đề t&agrave;i miền n&uacute;i, số phận v&agrave; hạnh ph&uacute;c của<strong>&nbsp;</strong>phụ nữ<strong>&nbsp;</strong>nơi đ&acirc;y.</p>\r\n\r\n<p>Nh&agrave; nghi&ecirc;n cứu, ph&ecirc; b&igrave;nh văn học Ph&ugrave;ng Gia Thế n&oacute;i về t&aacute;c phẩm: &quot;Những truyện ngắn mang m&agrave;u sắc tự truyện, sự h&ograve;a quyện, những v&ugrave;ng đau giữa kh&aacute;ch thể v&agrave; chủ thể khơi gợi rất s&acirc;u v&agrave;o những buồn vui của kiếp người&quot;.</p>\r\n\r\n<p><img alt=\"Bìa Còn một đợt rét chót, đêm nay sẽ về, sách 193 trang. Ảnh: NXB Hội Nhà văn\" src=\"https://i1-giaitri.vnecdn.net/2024/12/16/99452631c8a9c7784c56a30268a1c6-4755-7339-1734315173.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=UCjy1OsXcrHgA2ZvcNFMkQ\" /></p>\r\n\r\n<p>B&igrave;a &quot;C&ograve;n một đợt r&eacute;t ch&oacute;t, đ&ecirc;m nay sẽ về&quot;, s&aacute;ch 193 trang, ra mắt ng&agrave;y 1/12. Ảnh:&nbsp;<em>NXB Hội Nh&agrave; văn</em></p>\r\n\r\n<p>Số phận phụ nữ v&ugrave;ng cao được khắc họa trong truyện ngắn&nbsp;<em>Trước mặt l&agrave; n&uacute;i, sau lưng l&agrave; đ&aacute;</em>. Truyện xoay quanh cuộc sống của Mỉ từ khi về l&agrave;m vợ X&uacute;a, cậu b&eacute; 10 tuổi, kh&ocirc;ng hiểu r&otilde; kh&aacute;i niệm &quot;vợ chồng&quot; v&agrave; xa l&aacute;nh Mỉ, khiến c&ocirc; phải chịu đau đớn v&agrave; c&ocirc; đơn. Khi lớn l&ecirc;n, bắt đầu hiểu được t&igrave;nh cảm v&agrave; tr&aacute;ch nhiệm với vợ, X&uacute;a lại theo bố xuống th&agrave;nh phố l&agrave;m phụ hồ để kiếm tiền. Thời gian chồng đi xa, Mỉ mang thai, một m&igrave;nh c&ocirc; chăm s&oacute;c con kh&ocirc;n lớn.</p>\r\n\r\n<p>S&aacute;ch c&oacute; đoạn: &quot;Thầy lang bảo Mỉ c&oacute; thai, những ng&agrave;y chờ đợi c&agrave;ng th&ecirc;m bồn chồn, khắc khoải. Một đ&ocirc;ng. Hai đ&ocirc;ng... lại ba đ&ocirc;ng. Ngần ấy c&aacute;i đ&ocirc;ng, chưa c&oacute; đ&ocirc;ng n&agrave;o X&uacute;a về nh&agrave;. Những l&aacute; thư ngơi ngớt dần như những cơn mưa kh&ocirc;ng t&igrave;m tới đỉnh n&uacute;i Xao Va v&agrave;o m&ugrave;a đ&ocirc;ng&quot;.</p>\r\n\r\n<p>Phải đợi X&uacute;a lớn, chờ chồng trở về, người vợ ấy đ&aacute;ng lẽ c&oacute; một m&aacute;i ấm hạnh ph&uacute;c, nhưng thứ c&ocirc; nhận lại l&agrave; sự phản bội. Sau những năm xa nh&agrave;, chồng Mỉ về, mang theo người đ&agrave;n b&agrave; kh&aacute;c v&agrave; con ri&ecirc;ng của họ. Truyện kết th&uacute;c ở cảnh c&ocirc; g&aacute;i bế con ra khỏi nh&agrave;, kh&ocirc;ng chấp nhận chung chồng: &quot;Mỉ c&oacute; thể v&ugrave;i tuổi xu&acirc;n v&agrave;o tro bếp, chờ người đến h&oacute;a đ&aacute; nhưng đừng ai xin Mỉ phải chia chồng&quot;.</p>\r\n\r\n<p>Nh&agrave; văn cho thấy t&igrave;nh y&ecirc;u vượt định kiến của Du d&agrave;nh cho Vũ - người phụ nữ một đời chồng, nu&ocirc;i hai con nhỏ trong&nbsp;<em>Vệt nắng cuối rẻo đồi</em>. Anh bỏ qua lời đ&agrave;m tiếu, ở b&ecirc;n chăm s&oacute;c c&ocirc; v&agrave; c&aacute;c con. Nh&agrave; văn gửi gắm hy vọng về t&igrave;nh y&ecirc;u khi Vũ d&aacute;m vượt qua chồng cũ vũ phu để ở b&ecirc;n người m&igrave;nh y&ecirc;u.</p>\r\n\r\n<p>Theo PGS.TS, nh&agrave; gi&aacute;o ưu t&uacute; Nguyễn Đức Hạnh, nh&acirc;n vật của Trang Thụy l&agrave; những con người ngh&egrave;o khổ, &iacute;t học, ở dưới đ&aacute;y x&atilde; hội. &quot;Ở trong c&aacute;i tăm tối ấy, ch&uacute;ng ta y&ecirc;u họ v&igrave; kh&aacute;t vọng hạnh ph&uacute;c lấp l&aacute;nh như ngọn than hồng&quot;, &ocirc;ng n&oacute;i.</p>\r\n\r\n<p>C&aacute;c nh&acirc;n vật kh&ocirc;ng cam chịu số phận, chấp nhận để người kh&aacute;c định đoạt hạnh ph&uacute;c. Ở&nbsp;<em>M&ugrave;a cỏ đắng</em>, Trang l&agrave; mẹ đơn th&acirc;n nhưng quyết kh&ocirc;ng nghe theo sự sắp đặt của mẹ để ở lại l&agrave;ng qu&ecirc; v&agrave; trở th&agrave;nh vợ của Cường, người đ&agrave;n &ocirc;ng l&agrave;m nghề ch&egrave;o đ&ograve;, đ&aacute;nh c&aacute;. C&ocirc; cho rằng anh v&agrave; m&igrave;nh kh&ocirc;ng hợp: &quot;Ai cũng c&oacute; nơi để cắm rễ, giống người đ&agrave;n &ocirc;ng một mực ở lại với d&ograve;ng s&ocirc;ng, cặm cụi ngồi v&aacute; những lỗ thủng tr&ecirc;n lưới như đang v&aacute; lại đời m&igrave;nh. Việc l&ecirc;n bờ hay ở lại với t&ocirc;m c&aacute; kh&ocirc;ng quyết định y c&oacute; vợ hay kh&ocirc;ng, v&igrave; cuộc đời l&agrave; những chuỗi ng&agrave;y t&igrave;m kiếm sự ph&ugrave; hợp&quot;.</p>\r\n\r\n<p>T&aacute;c phẩm khắc họa h&igrave;nh ảnh người con t&igrave;m về với bố mẹ sau cuộc h&ocirc;n nh&acirc;n tan vỡ. Nh&acirc;n vật t&ocirc;i trong&nbsp;<em>M&ugrave;a trắng x&oacute;a</em>&nbsp;về nh&agrave; để b&aacute;o tin m&igrave;nh sắp ly h&ocirc;n, c&ocirc; c&oacute; suy nghĩ thấm th&iacute;a về mẹ v&agrave; h&ocirc;n nh&acirc;n: &quot;Ng&agrave;y t&ocirc;i c&atilde;i cha, c&atilde;i mẹ v&igrave; người dưng cũng v&agrave;o một m&ugrave;a thu đầy kh&oacute;i. Ng&agrave;y t&ocirc;i đi, kh&oacute;i hoen nh&egrave;m mắt mẹ, c&oacute; ai ngờ l&uacute;c long đong nhất vẫn chỉ biết về l&agrave;ng, t&igrave;m tới vai mẹ kh&oacute;c tu tu. Nh&acirc;n gian n&agrave;y rộng lớn như vậy, chỉ c&oacute; đ&ocirc;i vai mẹ l&agrave; rộng lượng v&ocirc; c&ugrave;ng&quot;.</p>\r\n\r\n<p>Nh&agrave; văn gửi gắm th&ocirc;ng điệp về hạnh ph&uacute;c của phụ nữ. Theo nh&agrave; thơ Văn C&ocirc;ng H&ugrave;ng, đọc xong t&aacute;c phẩm lại thấy một &quot;nỗi buồn như đ&aacute;. Để rồi hy vọng v&agrave; thương những th&acirc;n phận đ&agrave;n b&agrave;&quot;.</p>\r\n\r\n<p>C&aacute;c truyện ngắn c&oacute; lối viết tự nhi&ecirc;n, ng&ocirc;n ngữ<strong>&nbsp;</strong>sắc b&eacute;n kết hợp biện ph&aacute;p so s&aacute;nh. Nh&agrave; thơ Đỗ Anh Vũ nhận x&eacute;t về tập truyện: &quot;T&aacute;c giả sử dụng c&aacute;ch d&ugrave;ng từ mới mẻ, li&ecirc;n tưởng so s&aacute;nh chưa từng thấy, c&aacute;c đơn vị từ mới, diễn tả sự kh&aacute;c biệt, u &aacute;m của thi&ecirc;n nhi&ecirc;n. Sự tinh tế v&agrave; biểu cảm trong ng&ocirc;n ngữ l&agrave; điểm mạnh trong văn Trang Thụy, được kết hợp với những cốt truyện nhiều tầng bậc, c&oacute; sức &aacute;m gợi&quot;.</p>\r\n\r\n<p><img alt=\"Tác giả Trang Thụy. Ảnh: Hội Nhà văn Việt Nam\" src=\"https://i1-giaitri.vnecdn.net/2024/12/16/trang-thuy-vanvn3-1-1734314521-9833-9829-1734315173.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=-BTQ9uHS34h1JzltmzG1XA\" /></p>\r\n\r\n<p>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;T&aacute;c giả Trang Thụy. Ảnh:&nbsp;<em>Hội Nh&agrave; văn Việt Nam</em></p>\r\n\r\n<p>Trang Thụy t&ecirc;n thật l&agrave; Nguyễn Thị Trang, 35 tuổi, qu&ecirc; H&agrave; Tĩnh, hiện sinh sống v&agrave; l&agrave;m việc tại Hội An. C&ocirc; tốt nghiệp Khoa l&yacute; luận ch&iacute;nh trị Học viện B&aacute;o ch&iacute;. Nh&agrave; văn được biết đến với c&aacute;c truyện ngắn đăng tr&ecirc;n diễn đ&agrave;n văn học như&nbsp;<em>Duy&ecirc;n muộn</em>,&nbsp;<em>&Ocirc; mai g&oacute;t</em>,&nbsp;<em>C&ograve;n một đợt r&eacute;t ch&oacute;t, đ&ecirc;m nay sẽ về</em>.</p>\r\n','25/12/2024 16:20:35'),(3,'Châu Anh',NULL,'2024-12-27 15:28:48.788573','chu-heo-giang-sinh-1735029102-3352-1735029285.jpg','\'Chú heo Giáng sinh\' - cuộc phiêu lưu của những món đồ chơi',NULL,'<p>J.K. Rowling - t&aacute;c giả &quot;Harry Potter&quot; - viết về h&agrave;nh tr&igrave;nh t&igrave;m kiếm đồ chơi bị mất của cậu b&eacute; Jack trong &#39;&#39;Ch&uacute; heo Gi&aacute;ng sinh&#39;&#39;.</p>\r\n\r\n<p>T&aacute;c phẩm c&oacute; t&ecirc;n tiếng Anh l&agrave;&nbsp;<em>The Christmas Pig</em>, được J.K.Rowling s&aacute;ng t&aacute;c d&agrave;nh cho thiếu nhi. S&aacute;ch xuất bản lần đầu năm 2021 v&agrave; nhận được phản ứng t&iacute;ch cực từ độc giả.</p>\r\n\r\n<p>Truyện kể về h&agrave;nh tr&igrave;nh t&igrave;m lại đồ chơi thất lạc Heo Em của Jack, đồng h&agrave;nh cậu b&eacute; l&agrave; Ch&uacute; Heo Gi&aacute;ng sinh, c&ograve;n được gọi l&agrave; Heo Anh, vật thay thế của Heo Em. H&agrave;nh tr&igrave;nh t&igrave;m lại m&oacute;n đồ chơi bắt đầu v&agrave;o đ&ecirc;m trước Gi&aacute;ng sinh, khi mọi đồ vật bao gồm Heo Gi&aacute;ng sinh thức giấc, ch&uacute; gấu b&ocirc;ng b&agrave;y c&aacute;ch để Jack t&igrave;m lại Heo Em. Trong cuộc phi&ecirc;u lưu tại Xứ Mất, Jack gặp những m&oacute;n đồ hay gi&aacute; trị bị đ&aacute;nh mất, lắng nghe c&acirc;u chuyện của họ.</p>\r\n\r\n<p>T&aacute;c giả J.K.Rowling viết về t&igrave;nh y&ecirc;u thương trong cuốn s&aacute;ch. Heo Em như người bạn đồng h&agrave;nh với Jack từ khi c&ograve;n nhỏ. Ch&uacute; gấu b&ocirc;ng chứng kiến mọi khoảnh khắc vui buồn của cậu b&eacute;, vỗ về khi em kh&oacute;c v&igrave; bố mẹ chia tay: &#39;&#39;Bộ gi&ograve; ch&uacute;t ch&iacute;t cứ lau nước mắt cho Jack. Trong b&oacute;ng tối, Jack kh&ocirc;ng phải giả bộ g&igrave; với Heo Em&#39;&#39;.</p>\r\n\r\n<p>Khi m&oacute;n đồ chơi biến mất, cậu b&eacute; rơi v&agrave;o hoảng loạn: &#39;&#39;Tr&ecirc;n đời n&agrave;y chỉ c&oacute; mỗi Heo Em biết hết, l&uacute;c n&agrave;o cũng quan t&acirc;m, kh&ocirc;ng bao giờ thay đổi. V&agrave; Heo Em cần Jack bởi chỉ c&oacute; hai đứa mới hiểu nhau, m&agrave; giờ đ&acirc;y Heo Em nằm đ&acirc;u đ&oacute; tr&ecirc;n xa lộ, cứ tưởng bị Jack bỏ rơi rồi&#39;&#39;. V&igrave; những thay đổi khi bố mẹ chia tay, Jack c&agrave;ng phụ thuộc hơn v&agrave;o m&oacute;n đồ chơi, coi đ&oacute; l&agrave; người bạn t&acirc;m giao.</p>\r\n\r\n<p>Mượn thế giới trẻ con, nh&agrave; văn viết về những vấn đề của người lớn: sự tổn thương của con trẻ khi gia đ&igrave;nh tan vỡ, những gi&aacute; trị đ&atilde; bị con người đ&aacute;nh mất như hạnh ph&uacute;c, niềm hy vọng, lạc quan. Độc giả Maria viết tr&ecirc;n trang&nbsp;<em>Goodreads</em>: &#39;&#39;T&aacute;c giả kh&ocirc;ng chỉ kh&aacute;m ph&aacute; nhiều vấn đề như ly h&ocirc;n, sự mất m&aacute;t, tin tưởng, t&igrave;nh y&ecirc;u, t&igrave;nh bạn m&agrave; c&ograve;n tạo ra một cốt truyện đầy phi&ecirc;u lưu, kỳ diệu v&agrave; kinh ngạc&#39;&#39;.</p>\r\n\r\n<p>J.K. Rowling sử dụng ng&ocirc;n ngữ trong s&aacute;ng, th&acirc;n thuộc với trẻ nhỏ, thổi hồn v&agrave;o đồ vật khiến ch&uacute;ng c&oacute; thể giao tiếp, sinh hoạt như con người. Nh&agrave; văn gửi gắm th&ocirc;ng điệp về sức mạnh của t&igrave;nh y&ecirc;u thương. Cậu b&eacute; Jack trong truyện kh&ocirc;ng ngại hiểm nguy để mang người bạn của m&igrave;nh trở về, v&agrave; khi người ta y&ecirc;u một thứ g&igrave; đ&oacute; thật nhiều, thứ ấy kh&ocirc;ng bao giờ mất đi m&agrave; sẽ sống m&atilde;i ở một nơi tuyệt đẹp. S&aacute;ch c&oacute; đoạn: &#39;&#39;H&ograve;n đảo n&agrave;y vốn l&agrave; nơi quen thuộc với m&igrave;nh. Những vật được y&ecirc;u thương s&acirc;u sắc th&igrave; được xuống thẳng dưới Đảo Dấu Y&ecirc;u mỗi khi bị mất. T&igrave;nh thương của con người đ&atilde; khiến tụi m&igrave;nh th&agrave;nh bất tử&#39;&#39;.</p>\r\n\r\n<p>Tr&ecirc;n trang d&agrave;nh cho độc giả của m&igrave;nh, J.K.Rowling viết: &#39;&#39;T&ocirc;i rất mong cuốn s&aacute;ch c&oacute; thể tạo ra những cuộc tr&ograve; chuyện giữa c&aacute;c độc giả trẻ v&agrave; người lớn khi đọc s&aacute;ch, về những điều ch&uacute;ng ta tr&acirc;n trọng, về việc thay đổi v&agrave; mất m&aacute;t l&agrave; những phần kh&ocirc;ng thể tr&aacute;nh khỏi của cuộc sống, nhưng đồng thời, điều tuyệt vời vẫn c&oacute; thể đến từ sự thay đổi đ&oacute;&#39;&#39;.</p>\r\n\r\n<p><a href=\"https://vnexpress.net/tag/j-k-rowling-118482\">J.K Rowling</a>&nbsp;t&ecirc;n thật Joanne Rowling, 59 tuổi, sinh tại Yates, Glouceshire, Scotland, l&agrave; nh&agrave; văn, nh&agrave; từ thiện, nh&agrave; sản xuất phim v&agrave; truyền h&igrave;nh, bi&ecirc;n kịch người Anh. B&agrave; được biết đến với bộ truyện giả tưởng&nbsp;<em>Harry Potter</em>, viết về những cuộc phi&ecirc;u lưu của cậu b&eacute; Harry Potter c&ugrave;ng hai người bạn th&acirc;n l&agrave; Ron Weasley v&agrave; Hermione Granger, lấy bối cảnh tại Trường Ph&ugrave; thủy v&agrave; Ph&aacute;p sư Hogwarts ở nước Anh.</p>\r\n','27/12/2024 15:28:48'),(4,'Văn Phong',NULL,'2024-12-27 15:31:26.957140','085e5d3cc4701ed27d16c2fcfb80e6-6207-1245-1733278105.jpg','\'Đi về phía bình yên\' - tìm lại hạnh phúc',NULL,'<p>C&ocirc; g&aacute;i kể qu&aacute; khứ bị người th&acirc;n x&acirc;m hại, người phụ nữ viết c&acirc;u chuyện bị chồng bạo h&agrave;nh trong &quot;Đi về ph&iacute;a b&igrave;nh y&ecirc;n&quot;.</p>\r\n\r\n<p>Cuốn s&aacute;ch l&agrave; tự truyện của 12 phụ nữ trong số 1.665 mảnh đời ở Ng&ocirc;i nh&agrave; b&igrave;nh y&ecirc;n - nơi tạm tr&uacute; cho phụ nữ v&agrave; trẻ em bị bạo lực tr&ecirc;n cơ sở giới - thuộc Trung t&acirc;m Phụ nữ v&agrave; Ph&aacute;t triển, Hội Li&ecirc;n hiệp Phụ nữ Việt Nam. C&aacute;c nh&acirc;n vật chọn n&oacute;i ra c&acirc;u chuyện đời m&igrave;nh với mong muốn lan tỏa niềm tin v&agrave; hy vọng. T&aacute;c phẩm cho thấy<strong>&nbsp;</strong>ho&agrave;n cảnh của họ v&agrave; h&agrave;nh tr&igrave;nh bước ra khỏi b&oacute;ng tối, l&ecirc;n tiếng cho những nạn nh&acirc;n bị bạo h&agrave;nh, x&acirc;m hại, mua b&aacute;n người.</p>\r\n\r\n<p>C&aacute;c c&acirc;u chuyện trong t&aacute;c phẩm được lược bỏ một số t&igrave;nh tiết ti&ecirc;u cực nhưng vẫn c&oacute; t&iacute;nh ch&acirc;n thực. T&ecirc;n người v&agrave; địa danh đ&atilde; thay đổi để đảm bảo an to&agrave;n cho nh&acirc;n vật.</p>\r\n\r\n<p>S&aacute;ch n&oacute;i về b&eacute; g&aacute;i bị bố ruột x&acirc;m hại. Bố mẹ c&ocirc; ly h&ocirc;n khi con g&aacute;i mới được 1-2 th&aacute;ng, c&ocirc; b&eacute; lớn l&ecirc;n trong sự thiếu thốn t&igrave;nh thương, chứng kiến bố lấy vợ hai, vợ ba. &quot;Nếu sự việc x&acirc;m hại t&ocirc;i kh&ocirc;ng bị vỡ lở, c&oacute; lẽ giờ n&agrave;y bố đang ở với c&ocirc; ba, hoặc c&ocirc; tư, c&ocirc; năm n&agrave;o đ&oacute; nữa chưa biết chừng&quot;, người con g&aacute;i cho biết. Sau n&agrave;y, khi người bố đi t&ugrave;, c&ocirc; g&aacute;i bị nh&agrave; nội quay lưng, mẹ ruột đổ lỗi do con quyến rũ bố. Sự thờ ơ của gia đ&igrave;nh đ&atilde; để lại chấn thương t&acirc;m l&yacute;, c&ocirc; g&aacute;i t&igrave;m đến Ng&ocirc;i nh&agrave; b&igrave;nh y&ecirc;n để được trị liệu v&agrave; chữa l&agrave;nh những tổn thương. Hiện c&ocirc; học nghề v&agrave; sắp đi thực tập ở kh&aacute;ch sạn, nh&agrave; h&agrave;ng lớn.</p>\r\n\r\n<p>C&ocirc; nhớ về thời gian trước khi sự việc xảy ra, những ng&agrave;y hạnh ph&uacute;c b&ecirc;n bố v&agrave; anh trai: &quot;Mỗi lần nghe giọng bố, t&ocirc;i kh&oacute;c rất nhiều. T&ocirc;i kh&oacute;c kh&ocirc;ng phải v&igrave; nghĩ l&uacute;c bố l&agrave;m sai m&agrave; t&ocirc;i nh&igrave;n lại những khoảnh khắc tốt đẹp l&uacute;c bố con c&ograve;n vui vẻ. Bố, một người đ&agrave;n &ocirc;ng trải qua ba đời vợ nhưng về cơ bản vẫn l&agrave; g&agrave; trống nu&ocirc;i con. T&ocirc;i nhớ đ&ecirc;m trung thu ba bố con ngồi ăn b&aacute;nh ngắm trăng. T&ocirc;i kh&oacute;c v&igrave; kh&ocirc;ng thể quay lại khoảng thời gian v&ocirc; tư đ&oacute;&quot;.</p>\r\n\r\n<p>Bi&ecirc;n tập Trương Thị Ngọc Lan, người trực tiếp phỏng vấn gần 12 nh&acirc;n vật trong t&aacute;c phẩm, n&oacute;i đ&acirc;y l&agrave; ho&agrave;n cảnh khiến chị cảm động nhất. Chị cho biết: &quot;C&ocirc; g&aacute;i ấy n&oacute;i rằng b&acirc;y giờ em cảm thấy b&igrave;nh thường khi bố gọi từ trong t&ugrave;, nhưng anh trai gọi th&igrave; em lu&ocirc;n kh&oacute;c, bởi anh trai l&agrave; người chưa được chữa l&agrave;nh, sự việc khiến anh trai mất cả gia đ&igrave;nh, c&ograve;n em th&igrave; c&oacute; Ng&ocirc;i nh&agrave; b&igrave;nh y&ecirc;n rồi&quot;.</p>\r\n\r\n<p>H&agrave;nh tr&igrave;nh vượt qua cuộc h&ocirc;n nh&acirc;n kh&ocirc;ng hạnh ph&uacute;c, tho&aacute;t khỏi bạo lực gia đ&igrave;nh của nh&acirc;n vật B., c&ocirc; g&aacute;i miền n&uacute;i được kể lại trong&nbsp;<em>D&aacute;m bước qua ngạch cửa</em>. Theo quan điểm của người M&ocirc;ng, phụ nữ d&ugrave; bị chồng đ&aacute;nh, v&ugrave;i dập thế n&agrave;o cũng phải cam chịu. Kh&aacute;c với con g&aacute;i trong l&agrave;ng, B. lu&ocirc;n mơ ước được học rộng, đi nhiều nơi, c&ocirc; suy nghĩ m&igrave;nh c&oacute; thể tự lập được v&agrave; kh&ocirc;ng cần đến đ&agrave;n &ocirc;ng. B. quyết định vượt l&ecirc;n những định kiến, hủ tục khi ly h&ocirc;n chồng v&igrave; bị bạo h&agrave;nh, c&ocirc; l&agrave; người đầu ti&ecirc;n của bản d&aacute;m l&agrave;m điều n&agrave;y. H&agrave;nh động của B. l&agrave; động lực để những phụ nữ trong bản &quot;v&ugrave;ng l&ecirc;n&quot;, thay đổi nhận thức về h&ocirc;n nh&acirc;n trong họ.</p>\r\n\r\n<p>Trong s&aacute;ch c&oacute; đoạn: &quot;Ch&uacute;ng ta c&oacute; thể vấp ng&atilde;, c&oacute; thể sai lầm, c&oacute; thể đ&atilde; từng l&agrave; nạn nh&acirc;n của những điều kinh khủng nhất như bạo lực, x&acirc;m hại, mua b&aacute;n người... nhưng ch&uacute;ng ta vẫn c&oacute; thể sống s&oacute;t, sống mạnh mẽ v&agrave; tốt đẹp hơn, với sự nỗ lực của ch&iacute;nh ch&uacute;ng ta, c&ugrave;ng sự hỗ trợ của cộng đồng v&agrave; những ch&iacute;nh s&aacute;ch từ nh&agrave; nước hoặc nguồn t&agrave;i trợ của c&aacute;c tổ chức quốc tế, tổ chức thiện nguyện&quot;.</p>\r\n\r\n<p>Độc giả Th&ugrave;y Dương, 20 tuổi, H&agrave; Nội, cho biết kh&ocirc;ng khỏi nghẹn ng&agrave;o khi đọc cuốn s&aacute;ch: &quot;Mỗi c&acirc;u chuyện đều được kể lại với giọng văn ch&acirc;n thực, gi&agrave;u cảm x&uacute;c. Điều khiến t&ocirc;i x&uacute;c động nhất ch&iacute;nh l&agrave; nghị lực phi thường v&agrave; kh&aacute;t khao sống m&atilde;nh liệt của c&aacute;c nh&acirc;n vật.&nbsp;<em>Đi về ph&iacute;a b&igrave;nh y&ecirc;n</em>&nbsp;đ&atilde; dạy t&ocirc;i biết tr&acirc;n qu&yacute; hơn những gi&aacute; trị của cuộc sống&quot;.</p>\r\n\r\n<p>Chủ nhiệm c&acirc;u lạc bộ s&aacute;ch Nh&agrave; m&igrave;nh L&ecirc; Thị Th&ugrave;y Dương n&oacute;i: &quot;Đọc s&aacute;ch, t&ocirc;i đồng cảm với c&aacute;c nh&acirc;n vật, từ đ&oacute; nảy nở t&igrave;nh y&ecirc;u thương với những mảnh đời k&eacute;m may mắn&quot;.</p>\r\n\r\n<p><a href=\"https://vnexpress.net/chanh-van-hoang-anh-tu-dung-ep-tre-hoc-hay-de-tre-thich-hoc-3956978.html\">&quot;Ch&aacute;nh văn&quot; Ho&agrave;ng Anh T&uacute;</a>&nbsp;nhận x&eacute;t về cụm từ &quot;b&igrave;nh y&ecirc;n&quot; trong nhan đề t&aacute;c phẩm: &quot;Đ&oacute; l&agrave; một thứ rất kh&oacute; khăn, kh&ocirc;ng phải ai cũng c&oacute; sự b&igrave;nh y&ecirc;n. Tr&aacute;i tim phụ nữ lu&ocirc;n lo lắng, d&agrave;nh tất cả cho những người th&acirc;n y&ecirc;u của m&igrave;nh. V&igrave; vậy, b&igrave;nh y&ecirc;n l&agrave; m&oacute;n qu&agrave; v&ocirc; c&ugrave;ng gi&aacute; trị với mỗi người, l&agrave; nơi gi&ocirc;ng b&atilde;o dừng lại, nếu ch&uacute;ng ta c&oacute; thể chia sẻ với họ th&igrave; đ&oacute; l&agrave; một điều tuyệt vời&quot;.</p>\r\n\r\n<p><img alt=\"Chánh văn Hoàng Anh Tú nói về giá trị của sự bình yên đối với người phụ nữ. Ảnh: Trung tâm Phụ nữ và Phát triển\" src=\"https://i1-giaitri.vnecdn.net/2024/12/04/468736317-884166490563964-2199-5919-5821-1733278105.jpg?w=680&amp;h=0&amp;q=100&amp;dpr=1&amp;fit=crop&amp;s=dQ2nHIvGcuJWVswcOeVwbg\" /></p>\r\n\r\n<p>Nh&agrave; văn Ho&agrave;ng Anh T&uacute; n&oacute;i về gi&aacute; trị của sự b&igrave;nh y&ecirc;n đối với phụ nữ. Ảnh:&nbsp;<em>Trung t&acirc;m Phụ nữ v&agrave; Ph&aacute;t triển</em></p>\r\n\r\n<p>Cuốn s&aacute;ch truyền tải gi&aacute; trị t&iacute;ch cực trong việc bảo vệ phụ nữ, nhận thức về c&aacute;c vấn đề bạo lực giới, x&acirc;m hại t&igrave;nh dục v&agrave; mua b&aacute;n người, truyền cảm hứng để những nạn nh&acirc;n l&ecirc;n tiếng bảo vệ bản th&acirc;n v&agrave; những người xung quanh. S&aacute;ch gửi gắm th&ocirc;ng điệp về một gia đ&igrave;nh đ&uacute;ng nghĩa: &quot;Chỗ n&agrave;o an to&agrave;n, chỗ n&agrave;o hạnh ph&uacute;c, th&igrave; đấy l&agrave; gia đ&igrave;nh&quot;.</p>\r\n\r\n<p><em>Đi về ph&iacute;a b&igrave;nh y&ecirc;n</em>&nbsp;l&agrave; s&aacute;ch song ngữ bằng tiếng Việt v&agrave; tiếng Anh, ra mắt năm 2023, do Trung t&acirc;m Phụ nữ v&agrave; Ph&aacute;t triển l&agrave;m chủ bi&ecirc;n, NXB Phụ nữ Việt Nam ph&aacute;t h&agrave;nh. Kể từ khi ra mắt, cuốn s&aacute;ch được giới thiệu trong nhiều buổi giao lưu giữa c&aacute;c t&aacute;c giả, nh&acirc;n vật v&agrave; bạn đọc. Buổi tọa đ&agrave;m giới thiệu s&aacute;ch&nbsp;<em>Đi về ph&iacute;a b&igrave;nh y&ecirc;n</em>&nbsp;ng&agrave;y 29/11 được tổ chức trong Th&aacute;ng h&agrave;nh động v&igrave; b&igrave;nh đẳng giới.</p>\r\n\r\n<p><a href=\"https://vnexpress.net/ra-mat-trung-tam-phu-nu-va-phat-trien-1999486.html\">Trung t&acirc;m Phụ nữ v&agrave; Ph&aacute;t triển</a>&nbsp;(CWD) l&agrave; đơn vị thuộc Hội Li&ecirc;n hiệp Phụ nữ Việt nam (VWU), c&oacute; chức năng phục vụ c&aacute;c hoạt động ch&iacute;nh trị - x&atilde; hội của Hội v&agrave; hỗ trợ sự ph&aacute;t triển to&agrave;n diện về năng lực, tr&igrave;nh độ, kỹ năng nghề nghiệp, thể lực v&agrave; thẩm mỹ của phụ nữ Việt Nam. Trung t&acirc;m được ph&eacute;p cung cấp c&aacute;c dịch vụ kinh doanh để c&oacute; nguồn thu hỗ trợ cho phụ nữ yếu thế. CWD từng cho xuất bản cuốn&nbsp;<em>Ng&ocirc;i nh&agrave; B&igrave;nh y&ecirc;n: tự truyện của nạn nh&acirc;n bị mua b&aacute;n trở về</em>&nbsp;(2013).</p>\r\n','27/12/2024 15:31:26');
