  `is_active` bit(1) DEFAULT NULL,
  `isbn` varchar(255) DEFAULT NULL,
  `stock` int NOT NULL,
  `publisher` varchar(255) DEFAULT NULL,
  `discount` int NOT NULL,
  `discount_price` int DEFAULT NULL,
  `price` int DEFAULT NULL,
  `average_rating` double NOT NULL,
  `created_date` datetime(6) DEFAULT NULL,
  `formatted_discount_price` varchar(255) DEFAULT NULL,
  `formatted_price` varchar(255) DEFAULT NULL,
  `sold` int NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=372 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
