INSERT INTO `book` VALUES (1,'Nguyễn Văn A','Giải tích 1','Giáo trình','Tóm tắt lý thuyết và một số dạng bài tập của Giải tích 1','product-item1.png',_binary '','123456789123',20,'Kim Đồng',15,85000,100000,3.8333333333333335,NULL,'85,000','100,000',0),(2,'Nguyễn Văn b','Giải tích 2','Giáo trình','Tóm tắt lý thuyết và một số dạng bài tập của Giải tích 2','product-item2.png',_binary '','96585852320222',25,'Giáo Dục',20,120000,150000,2.6,NULL,'120,000','150,000',0),(4,'Du Ca','Goal Planer','Luận văn Thạc sĩ','goal planer','product-item3.png',_binary '','123456789123',0,'Kim Đồng',20,160000,200000,4,NULL,'160,000','200,000',0),(15,'Dale Carnegie','Đắc Nhân Tâm','Kĩ năng sống','Đắc Nhân Tâm là một trong những cuốn sách nổi tiếng về kỹ năng giao tiếp và xây dựng các mối quan hệ. Tác giả Dale Carnegie đã chia sẻ những bí quyết giúp con người trở nên thu hút và dễ dàng giao tiếp với người khác, từ đó xây dựng mối quan hệ tốt đẹp trong công việc và cuộc sống. Những bài học trong sách đều dựa trên các nguyên tắc đơn giản nhưng sâu sắc, giúp người đọc hiểu rõ hơn về cách thức tạo dựng lòng tin và sự tôn trọng từ người khác. Cuốn sách không chỉ giúp cải thiện các kỹ năng giao tiếp mà còn mở ra những cơ hội mới cho sự nghiệp và các mối quan hệ cá nhân.','dac nhan tam.jpg',_binary '','978-0-935131-06-1',95,'Kim Đồng',15,212500,250000,5,'2024-12-20 00:14:27.463536','212,500','250,000',5),(18,'Dale Carnegie','Đắc Nhân Tâm','Kỹ năng sống','Đắc Nhân Tâm là một trong những cuốn sách nổi tiếng về kỹ năng giao tiếp và xây dựng các mối quan hệ. Tác giả Dale Carnegie đã chia sẻ những bí quyết giúp con người trở nên thu hút và dễ dàng giao tiếp với người khác, từ đó xây dựng mối quan hệ tốt đẹp trong công việc và cuộc sống. Những bài học trong sách đều dựa trên các nguyên tắc đơn giản nhưng sâu sắc, giúp người đọc hiểu rõ hơn về cách thức tạo dựng lòng tin và sự tôn trọng từ người khác. Cuốn sách không chỉ giúp cải thiện các kỹ năng giao tiếp mà còn mở ra những cơ hội mới cho sự nghiệp và các mối quan hệ cá nhân.','https://tiki.vn/blog/wp-content/uploads/2023/08/noi-dung-chinh-dac-nhan-tam-1024x682.jpg',_binary '','978-0-935131-06-1',100,'First Publishing',10,90000,100000,0,NULL,'90,000','100,000',0),(19,'Yuval Noah Harari','Sapiens: Lược Sử Loài Người','Lịch sử','Sapiens: Lược Sử Loài Người là một cuốn sách nổi tiếng của tác giả Yuval Noah Harari, cung cấp một cái nhìn toàn diện về sự phát triển của loài người từ những ngày đầu sơ khai cho đến hiện đại. Từ sự xuất hiện của Homo sapiens, qua các cuộc cách mạng nông nghiệp, công nghiệp, đến sự bùng nổ của công nghệ và thông tin, Harari phân tích những yếu tố đã hình thành và dẫn dắt sự tiến hóa của xã hội, văn hóa và chính trị. Cuốn sách giúp người đọc hiểu rõ về những thay đổi lớn trong lịch sử loài người, đồng thời khơi dậy nhiều suy ngẫm về tương lai của nhân loại.','https://down-vn.img.susercontent.com/file/vn-11134207-7r98o-lveh8r4k8oel0a',_binary '','978-0-06-231609-7',150,'Dân Trí',15,127500,150000,0,NULL,'127,500','150,000',0),(20,'Angela Duckworth','Catcher','Kĩ năng sống','<p>Sách<br />\r\n- Sách 1<br />\r\n- Sách 2</p>\r\n\r\n<p><img alt=\"\" src=\"https://tiki.vn/blog/wp-content/uploads/2023/08/noi-dung-chinh-dac-nhan-tam-1024x682.jpg\" style=\"height:682px; width:1024px\" /></p>\r\n\r\n<p>Thủ tướng Ch&iacute;nh phủ vừa k&yacute; văn bản số 1098/TTg-QHĐP về việc triển khai thực hiện Nghị quyết tại Kỳ họp thứ 8, Quốc hội kh&oacute;a XV gửi: Ph&oacute; Thủ tướng Thường trực Ch&iacute;nh phủ Nguyễn H&ograve;a B&igrave;nh; c&aacute;c Ph&oacute; Thủ tướng Ch&iacute;nh phủ Trần Hồng H&agrave;, L&ecirc; Th&agrave;nh Long, Hồ Đức Phớc, B&ugrave;i Thanh Sơn; Bộ trưởng, Thủ trưởng cơ quan ngang Bộ, cơ quan thuộc Ch&iacute;nh phủ; Chủ tịch Ủy ban nh&acirc;n d&acirc;n tỉnh, th&agrave;nh phố trực thuộc Trung ương</p>\r\n\r\n<p>Để triển khai thực hiện nghi&ecirc;m t&uacute;c, kịp thời v&agrave; hiệu quả Nghị quyết số 173/2024/QH15 ng&agrave;y 30/11/2024 về hoạt động chất vấn tại Kỳ họp thứ 8 v&agrave; Nghị quyết số 174/2024/QH15 ng&agrave;y 30/11/2024 về Kỳ họp thứ 8 của Quốc hội kh&oacute;a XV, Thủ tướng Ch&iacute;nh phủ Phạm Minh Ch&iacute;nh đề nghị c&aacute;c đồng ch&iacute; Ph&oacute; Thủ tướng Ch&iacute;nh phủ phụ tr&aacute;ch lĩnh vực trực tiếp chỉ đạo triển khai thực hiện c&aacute;c nội dung, nhiệm vụ, giải ph&aacute;p tại c&aacute;c Nghị quyết n&ecirc;u tr&ecirc;n của Quốc hội, bảo đảm đồng bộ, to&agrave;n diện, chất lượng, hiệu quả v&agrave; đ&uacute;ng tiến độ đề ra.</p>\r\n\r\n<p>Thủ tướng Ch&iacute;nh phủ y&ecirc;u cầu Bộ trưởng, Thủ trưởng cơ quan ngang bộ, cơ quan thuộc Ch&iacute;nh phủ theo chức năng, nhiệm vụ, thẩm quyền được giao, trực tiếp chỉ đạo tổ chức triển khai thực hiện Nghị quyết số 173/2024/QH15 v&agrave; Nghị quyết số 174/2024/QH15 của Quốc hội, theo d&otilde;i s&aacute;t diễn biến, dự b&aacute;o t&igrave;nh h&igrave;nh trong nước v&agrave; thế giới, c&oacute; giải ph&aacute;p ch&iacute;nh s&aacute;ch ph&ugrave; hợp, s&aacute;t thực tiễn, cụ thể, khả thi để khắc phục c&aacute;c tồn tại, hạn chế v&agrave; tổ chức thực hiện quyết liệt, bảo đảm tiến độ, chất lượng, hiệu quả; tăng cường tuy&ecirc;n truyền, phổ biến, gi&aacute;o dục ph&aacute;p luật để sớm triển khai thực hiện c&aacute;c luật, nghị quyết đ&atilde; được Quốc hội th&ocirc;ng qua; h&agrave;ng th&aacute;ng b&aacute;o c&aacute;o v&agrave; chịu tr&aacute;ch nhiệm trước Ch&iacute;nh phủ, Thủ tướng Ch&iacute;nh phủ về kết quả thực hiện.</p>\r\n','the-catcher-in-the-rye-jd-salinger-first-edition-rare-signed.webp',_binary '','978-0-06-231609-7',50,'NXB Trẻ',15,153000,180000,0,'2024-12-22 20:28:39.123148','153,000','180,000',0),(21,'Dale Carnegie','Đắc Nhân Tâm','Kỹ năng sống','Đắc Nhân Tâm là một trong những cuốn sách nổi tiếng về kỹ năng giao tiếp và xây dựng các mối quan hệ. Tác giả Dale Carnegie đã chia sẻ những bí quyết giúp con người trở nên thu hút và dễ dàng giao tiếp với người khác, từ đó xây dựng mối quan hệ tốt đẹp trong công việc và cuộc sống. Những bài học trong sách đều dựa trên các nguyên tắc đơn giản nhưng sâu sắc, giúp người đọc hiểu rõ hơn về cách thức tạo dựng lòng tin và sự tôn trọng từ người khác. Cuốn sách không chỉ giúp cải thiện các kỹ năng giao tiếp mà còn mở ra những cơ hội mới cho sự nghiệp và các mối quan hệ cá nhân.','https://tiki.vn/blog/wp-content/uploads/2023/08/noi-dung-chinh-dac-nhan-tam-1024x682.jpg',_binary '','978-0-935131-06-1',100,'First Publishing',10,90000,100000,0,NULL,NULL,NULL,0),(23,'Dale Carnegie','Đắc Nhân Tâm','Kỹ năng sống','Đắc Nhân Tâm là một trong những cuốn sách nổi tiếng về kỹ năng giao tiếp và xây dựng các mối quan hệ. Tác giả Dale Carnegie đã chia sẻ những bí quyết giúp con người trở nên thu hút và dễ dàng giao tiếp với người khác, từ đó xây dựng mối quan hệ tốt đẹp trong công việc và cuộc sống. Những bài học trong sách đều dựa trên các nguyên tắc đơn giản nhưng sâu sắc, giúp người đọc hiểu rõ hơn về cách thức tạo dựng lòng tin và sự tôn trọng từ người khác. Cuốn sách không chỉ giúp cải thiện các kỹ năng giao tiếp mà còn mở ra những cơ hội mới cho sự nghiệp và các mối quan hệ cá nhân.','https://tiki.vn/blog/wp-content/uploads/2023/08/noi-dung-chinh-dac-nhan-tam-1024x682.jpg',_binary '','978-0-935131-06-1',100,'First Publishing',10,90000,100000,0,NULL,NULL,NULL,0),(24,'Yuval Noah Harari','Sapiens: Lược Sử Loài Người','Lịch sử','Sapiens: Lược Sử Loài Người là một cuốn sách nổi tiếng của tác giả Yuval Noah Harari, cung cấp một cái nhìn toàn diện về sự phát triển của loài người từ những ngày đầu sơ khai cho đến hiện đại. Từ sự xuất hiện của Homo sapiens, qua các cuộc cách mạng nông nghiệp, công nghiệp, đến sự bùng nổ của công nghệ và thông tin, Harari phân tích những yếu tố đã hình thành và dẫn dắt sự tiến hóa của xã hội, văn hóa và chính trị. Cuốn sách giúp người đọc hiểu rõ về những thay đổi lớn trong lịch sử loài người, đồng thời khơi dậy nhiều suy ngẫm về tương lai của nhân loại.','https://down-vn.img.susercontent.com/file/vn-11134207-7r98o-lveh8r4k8oel0a'